'use client'
import { motion } from 'framer-motion'
import { useCallback } from "react"
import Particles from "react-tsparticles"
import { loadSlim } from "tsparticles-slim"
import { useTheme } from '../context/ThemeContext'
import { DiReact, DiJavascript1, DiPython, DiNodejs } from 'react-icons/di'
import { SiTypescript, SiNextdotjs, SiTailwindcss, SiMongodb, SiPostgresql, SiFigma } from 'react-icons/si'

export default function Skills() {
  const { isDark, theme } = useTheme()

  const particlesInit = useCallback(async engine => {
    await loadSlim(engine)
  }, [])

  const skillsData = [
    {
      category: "Frontend",
      items: [
        { name: "React", icon: DiReact, proficiency: 90 },
        { name: "Next.js", icon: SiNextdotjs, proficiency: 85 },
        { name: "JavaScript", icon: DiJavascript1, proficiency: 95 },
        { name: "TypeScript", icon: SiTypescript, proficiency: 80 },
        { name: "TailwindCSS", icon: SiTailwindcss, proficiency: 90 },
      ]
    },
    {
      category: "Backend",
      items: [
        { name: "Node.js", icon: DiNodejs, proficiency: 85 },
        { name: "Python", icon: DiPython, proficiency: 80 },
        { name: "MongoDB", icon: SiMongodb, proficiency: 75 },
        { name: "PostgreSQL", icon: SiPostgresql, proficiency: 70 },
      ]
    },
    {
      category: "Design",
      items: [
        { name: "Figma", icon: SiFigma, proficiency: 85 },
      ]
    }
  ]

  return (
    <section className={`min-h-screen flex items-center justify-center bg-gradient-to-br ${theme.bg} relative overflow-hidden transition-all duration-700 py-20`}>
      <Particles
        id="tsparticles-skills"
        init={particlesInit}
        options={{
          background: {
            color: {
              value: "transparent",
            },
          },
          fpsLimit: 120,
          interactivity: {
            events: {
              onHover: {
                enable: true,
                mode: "repulse",
              },
              onClick: {
                enable: true,
                mode: "push",
              },
            },
            modes: {
              repulse: {
                distance: 100,
                duration: 0.4,
              },
              push: {
                quantity: 4,
              },
            },
          },
          particles: {
            color: {
              value: [theme.primary, theme.secondary, theme.accent],
            },
            links: {
              color: theme.primary,
              distance: 150,
              enable: true,
              opacity: 0.5,
              width: 1,
            },
            move: {
              direction: "none",
              enable: true,
              outModes: {
                default: "bounce",
              },
              random: false,
              speed: 2,
              straight: false,
            },
            number: {
              density: {
                enable: true,
                area: 800,
              },
              value: 80,
            },
            opacity: {
              value: 0.5,
              animation: {
                enable: true,
                speed: 1,
                minimumValue: 0.1,
              },
            },
            shape: {
              type: "circle",
            },
            size: {
              value: { min: 1, max: 3 },
            },
          },
          detectRetina: true,
        }}
      />
      
      <div className="container mx-auto px-4 z-10">
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <h2 
            className="font-mono mb-4"
            style={{ color: theme.primary }}
          >
            What I Do
          </h2>
          <h3 
            className="text-4xl font-bold"
            style={{ color: theme.text }}
          >
            My Expertise
          </h3>
        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {skillsData.map((category, categoryIndex) => (
            <motion.div
              key={category.category}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: categoryIndex * 0.2 }}
              className="backdrop-blur-lg rounded-xl p-6"
              style={{
                backgroundColor: isDark ? 'rgba(10, 25, 47, 0.7)' : 'rgba(255, 255, 255, 0.7)',
                borderColor: theme.primary,
                borderWidth: '1px'
              }}
            >
              <h4 
                className="text-2xl font-bold mb-6"
                style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
              >
                {category.category}
              </h4>
              <div className="space-y-6">
                {category.items.map((skill, index) => (
                  <motion.div
                    key={skill.name}
                    initial={{ x: -50, opacity: 0 }}
                    whileInView={{ x: 0, opacity: 1 }}
                    transition={{ delay: index * 0.1 }}
                    whileHover={{ scale: 1.05 }}
                    className="relative"
                  >
                    <div className="flex items-center gap-4 mb-2">
                      <skill.icon 
                        className="w-6 h-6"
                        style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
                      />
                      <span style={{ color: theme.text }}>{skill.name}</span>
                    </div>
                    <div 
                      className="h-2 rounded-full"
                      style={{ backgroundColor: isDark ? '#1a1b26' : '#f0f0f0' }}
                    >
                      <motion.div
                        initial={{ width: 0 }}
                        whileInView={{ width: `${skill.proficiency}%` }}
                        transition={{ duration: 1, delay: index * 0.1 }}
                        className="h-full rounded-full"
                        style={{ 
                          backgroundColor: isDark ? '#bd93f9' : '#EDAFB8',
                        }}
                      />
                    </div>
                    <div 
                      className="absolute right-0 top-0"
                      style={{ color: theme.textSecondary }}
                    >
                      {skill.proficiency}%
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          ))}
        </div>

        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 1, delay: 0.5 }}
          className="text-center mt-16"
          style={{ color: theme.textSecondary }}
        >
          <p className="text-lg">
            Always learning and exploring new technologies to stay ahead in the ever-evolving tech landscape ✨
          </p>
        </motion.div>
      </div>
    </section>
  )
}
