'use client'
import { motion } from 'framer-motion'
import { useCallback, useState } from "react"
import Particles from "react-tsparticles"
import { loadSlim } from "tsparticles-slim"
import { useTheme } from '../context/ThemeContext'
import Image from 'next/image'

export default function Projects() {
  const { isDark, theme } = useTheme()
  const [activeMediaIndex, setActiveMediaIndex] = useState(0)

  const particlesInit = useCallback(async engine => {
    await loadSlim(engine)
  }, [])

  const projects = [
    {
      title: "AI-Powered Portfolio Generator",
      description: "A revolutionary tool that uses AI to automatically generate and customize professional portfolios based on user data and preferences. Built with cutting-edge technology to deliver personalized and professional results in minutes.",
      media: [
        {
          type: 'image',
          url: '/project1-main.jpg',
          alt: 'Dashboard view'
        },
        {
          type: 'video',
          url: '/project1-demo.mp4',
          thumbnail: '/project1-thumb.jpg'
        },
        {
          type: 'image',
          url: '/project1-feature.jpg',
          alt: 'AI generation process'
        }
      ],
      featured: true
    },
    {
      title: "Real-time Collaboration Platform",
      description: "A powerful platform enabling seamless real-time collaboration with features like live editing, video calls, and project management. Perfect for remote teams and digital workspaces.",
      media: [
        {
          type: 'image',
          url: '/project2-main.jpg',
          alt: 'Platform overview'
        },
        {
          type: 'video',
          url: '/project2-demo.mp4',
          thumbnail: '/project2-thumb.jpg'
        }
      ]
    },
    {
      title: "E-commerce Dashboard",
      description: "Advanced analytics dashboard for e-commerce businesses with AI-powered insights and predictions. Helps businesses make data-driven decisions and optimize their operations.",
      media: [
        {
          type: 'image',
          url: '/project3-main.jpg',
          alt: 'Dashboard analytics'
        },
        {
          type: 'image',
          url: '/project3-features.jpg',
          alt: 'Feature showcase'
        }
      ]
    }
  ]

  return (
    <section className={`min-h-screen flex items-center justify-center bg-gradient-to-br ${theme.bg} relative overflow-hidden transition-all duration-700 py-20`}>
      <Particles
        id="tsparticles-projects"
        init={particlesInit}
        options={{
          background: { color: { value: "transparent" } },
          fpsLimit: 120,
          interactivity: {
            events: {
              onHover: { enable: true, mode: "repulse" },
              onClick: { enable: true, mode: "push" },
            },
            modes: {
              repulse: { distance: 100, duration: 0.4 },
              push: { quantity: 4 },
            },
          },
          particles: {
            color: { value: [theme.primary, theme.secondary, theme.accent] },
            links: {
              color: theme.primary,
              distance: 150,
              enable: true,
              opacity: 0.5,
              width: 1,
            },
            move: {
              direction: "none",
              enable: true,
              outModes: { default: "bounce" },
              random: false,
              speed: 2,
              straight: false,
            },
            number: {
              density: { enable: true, area: 800 },
              value: 80,
            },
            opacity: {
              value: 0.5,
              animation: {
                enable: true,
                speed: 1,
                minimumValue: 0.1,
              },
            },
            shape: { type: "circle" },
            size: { value: { min: 1, max: 3 } },
          },
          detectRetina: true,
        }}
      />

      <div className="container mx-auto px-4 z-10">
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <h2 className="font-mono mb-4" style={{ color: theme.primary }}>
            My Work
          </h2>
          <h3 className="text-4xl font-bold" style={{ color: theme.text }}>
            Featured Projects
          </h3>
        </motion.div>

        <div className="space-y-32">
          {projects.map((project, index) => (
            <motion.div
              key={project.title}
              initial={{ opacity: 0, y: 100 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8 }}
              className={`flex flex-col ${index % 2 === 0 ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-8`}
            >
            {/* Project Media Showcase */}
<motion.div className="flex-1 relative group">
  <div className="relative overflow-hidden rounded-xl aspect-video">
    {project.media.map((media, mediaIndex) => (
      <motion.div
        key={mediaIndex}
        initial={{ opacity: 0 }}
        animate={{ opacity: mediaIndex === activeMediaIndex ? 1 : 0 }}
        transition={{ duration: 0.5 }}
        className="absolute inset-0"
      >
        {media.type === 'video' ? (
          <video
            autoPlay
            loop
            muted
            playsInline
            poster={media.thumbnail}
            className="w-full h-full object-cover"
          >
            <source src={media.url} type="video/mp4" />
          </video>
        ) : (
          <div className="relative w-full h-full">
            <Image
              src={media.url}
              alt={media.alt}
              fill
              className="object-cover"
            />
          </div>
        )}
      </motion.div>
    ))}
    
    {/* Navigation Arrows */}
    <div className="absolute inset-0 flex items-center justify-between p-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
      <motion.button
        onClick={() => setActiveMediaIndex(prev => 
          prev === 0 ? project.media.length - 1 : prev - 1
        )}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        className="w-10 h-10 rounded-full flex items-center justify-center backdrop-blur-sm"
        style={{ 
          backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
          color: isDark ? '#bd93f9' : '#EDAFB8'
        }}
      >
        <span className="text-2xl">&lt;</span>
      </motion.button>
      
      <motion.button
        onClick={() => setActiveMediaIndex(prev => 
          prev === project.media.length - 1 ? 0 : prev + 1
        )}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        className="w-10 h-10 rounded-full flex items-center justify-center backdrop-blur-sm"
        style={{ 
          backgroundColor: isDark ? 'rgba(189, 147, 249, 0.1)' : 'rgba(237, 175, 184, 0.1)',
          color: isDark ? '#bd93f9' : '#EDAFB8'
        }}
      >
        <span className="text-2xl">&gt;</span>
      </motion.button>
    </div>

                  
                  {/* Media Navigation Dots */}
                  <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex gap-2">
                    {project.media.map((_, index) => (
                      <motion.button
                        key={index}
                        onClick={() => setActiveMediaIndex(index)}
                        className={`w-2 h-2 rounded-full transition-all duration-300 ${
                          index === activeMediaIndex ? 'w-4' : ''
                        }`}
                        style={{
                          backgroundColor: index === activeMediaIndex 
                            ? isDark ? '#bd93f9' : '#EDAFB8'
                            : isDark ? '#bd93f940' : '#EDAFB840'
                        }}
                        whileHover={{ scale: 1.2 }}
                      />
                    ))}
                  </div>
                </div>
              </motion.div>

              {/* Project Info */}
              <motion.div
                className="flex-1 space-y-4"
                whileHover={{ x: index % 2 === 0 ? 20 : -20 }}
              >
                <h4 
                  className="text-2xl font-bold"
                  style={{ color: isDark ? '#bd93f9' : '#EDAFB8' }}
                >
                  {project.title}
                </h4>
                
                <p 
                  className="text-lg"
                  style={{ color: theme.textSecondary }}
                >
                  {project.description}
                </p>
              </motion.div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}
